int main(void){_Alignas(16) unsigned char buf[256];heap_init(buf,sizeof buf);char out[100];size_t n=heap_map(out,sizeof out);CHECK("empty allocation map",n==16&&strcmp(out,"H...............")==0,"%s",out);void*a=heap_alloc(32);void*b=heap_alloc(16);heap_free(a);n=heap_map(out,sizeof out);CHECK("fragmented map",n==16&&strcmp(out,"H..HUH..........")==0,"%s",out);char expected[100];strcpy(expected,out);for(size_t cap=0;cap<20;cap++){char small[30];memset(small,'X',sizeof small);size_t got=heap_map(cap?small:NULL,cap);int ok=got==16;if(cap){size_t len=cap-1<16?cap-1:16;ok=ok&&small[len]==0&&memcmp(small,expected,len)==0&&small[cap]=='X';}CHECK("bounded output",ok,"cap %zu",cap);}heap_free(b);heap_map(out,sizeof out);CHECK("coalesced",strcmp(out,"H...............")==0,"%s",out);heap_init(buf,0);CHECK("zero heap",heap_map(out,sizeof out)==0&&out[0]==0,"empty");return 0;}
